package br.com.equilibra.budget.application;
import br.com.equilibra.budget.api.BudgetSummaryDtos; import br.com.equilibra.budget.domain.CategoryBudget; import br.com.equilibra.budget.infrastructure.CategoryBudgetRepository; import br.com.equilibra.category.domain.Category; import br.com.equilibra.category.infrastructure.CategoryRepository; import br.com.equilibra.shared.api.CurrentUser; import br.com.equilibra.shared.web.exception.ResourceNotFoundException; import br.com.equilibra.transaction.domain.TransactionStatus; import br.com.equilibra.transaction.infrastructure.FinancialTransactionRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service public class BudgetSummaryService { private final CategoryBudgetRepository budgets; private final CategoryRepository categories; private final FinancialTransactionRepository transactions; private final CurrentUser currentUser; public BudgetSummaryService(CategoryBudgetRepository b,CategoryRepository c,FinancialTransactionRepository t,CurrentUser u){budgets=b;categories=c;transactions=t;currentUser=u;}
 @Transactional(readOnly=true) public BudgetSummaryDtos.Response summary(String month){YearMonth ym=parse(month);Instant from=ym.atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant(),to=ym.plusMonths(1).atDay(1).atStartOfDay(ZoneOffset.UTC).toInstant();String owner=currentUser.id().toString();List<CategoryBudget> bs=budgets.findAllByOwnerIdOrderByYearDescMonthDesc(owner).stream().filter(b->b.getYear()==ym.getYear()&&b.getMonth()==ym.getMonthValue()).toList();List<String> ids=bs.stream().map(CategoryBudget::getCategoryId).toList();Map<String,BigDecimal> actual=new HashMap<>();if(!ids.isEmpty())for(var row:transactions.sumActiveExpensesByCategory(owner,TransactionStatus.ACTIVE,from,to,ids))actual.put(row.getCategoryId(),row.getAmount());List<BudgetSummaryDtos.Breakdown> lines=bs.stream().map(b->{Category c=categories.findByIdAndOwnerId(b.getCategoryId(),owner).orElseThrow(()->new ResourceNotFoundException("Category not found."));BigDecimal a=actual.getOrDefault(b.getCategoryId(),BigDecimal.ZERO).setScale(2),p=b.getPlannedAmount(),remaining=p.subtract(a);BigDecimal percentage=p.signum()==0?null:a.multiply(BigDecimal.valueOf(100)).divide(p,2,RoundingMode.HALF_UP);BudgetSummaryDtos.Status status=p.signum()==0||percentage.compareTo(BigDecimal.valueOf(80))<0?BudgetSummaryDtos.Status.ON_TRACK:percentage.compareTo(BigDecimal.valueOf(100))<=0?BudgetSummaryDtos.Status.WARNING:BudgetSummaryDtos.Status.EXCEEDED;return new BudgetSummaryDtos.Breakdown(b.getId(),c.getId(),c.getName(),c.isActive(),p,a,remaining,percentage,status);}).toList();BigDecimal planned=lines.stream().map(BudgetSummaryDtos.Breakdown::plannedAmount).reduce(BigDecimal.ZERO,BigDecimal::add),act=lines.stream().map(BudgetSummaryDtos.Breakdown::actualAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return new BudgetSummaryDtos.Response(month,planned,act,planned.subtract(act),planned.signum()==0?null:act.multiply(BigDecimal.valueOf(100)).divide(planned,2,RoundingMode.HALF_UP),lines);}
 private YearMonth parse(String value){try{return YearMonth.parse(value);}catch(Exception e){throw new IllegalArgumentException("month must use YYYY-MM");}}
}
